/*
 Problem: 3720. Lexicographically Smallest Permutation Greater Than Target
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 11.3 MB (33.68%)
 Tags: Hash Table, String, Greedy, Counting, Enumeration
*/
class Solution {
public:
    string lexGreaterPermutation(string s, string target) {
        vector<int> cnt(26);
        for (char c : s) cnt[c - 'a']++;

        int pos = -1;
        char pick;

        for (int i = 0; i < s.size(); i++) {
            for (char c = target[i] + 1; c <= 'z'; c++) {
                if (cnt[c - 'a']) {
                    pos = i;
                    pick = c;
                    break;
                }
            }

            if (!cnt[target[i] - 'a'])
                break;

            cnt[target[i] - 'a']--;
        }

        if (pos == -1)
            return "";

        cnt.assign(26, 0);
        for (char c : s) cnt[c - 'a']++;

        string ans = target.substr(0, pos) + pick;

        for (int i = 0; i < pos; i++)
            cnt[target[i] - 'a']--;

        cnt[pick - 'a']--;

        for (int i = 0; i < 26; i++)
            ans += string(cnt[i], 'a' + i);

        return ans;
    }
};
